706	    if (!m[2]) return inner;
707	    return `${m[1]}${mark}${m[2]}${mark}${m[3]}`;
708	  }
709	
710	  function inline(node) {
711	    if (node.nodeType === 3) {
712	      const t = node.nodeValue.replace(/​/g, '').replace(/ /g, ' ').replace(/[ \t\r\n]+/g, ' ');
713	      return escapeMd(t);
714	    }
715	    if (node.nodeType !== 1) return '';
716	    const kids = () => Array.from(node.childNodes).map(inline).join('');
717	    switch (node.tagName) {
718	      case 'BR': return '  \n';
719	      case 'STRONG': case 'B': return wrap(kids(), '**');
720	      case 'EM': case 'I': return wrap(kids(), '*');
721	      case 'S': case 'STRIKE': case 'DEL': return wrap(kids(), '~~');
722	      case 'CODE': {
723	        const t = node.textContent.replace(/​/g, '').replace(/ /g, ' ');
724	        if (!t) return '';
725	        const fence = t.includes('`') ? '``' : '`';
726	        const pad = /^`|`$/.test(t) ? ' ' : '';
727	        return `${fence}${pad}${t}${pad}${fence}`;
728	      }
729	      case 'A': {
730	        const href = node.getAttribute('href') || '';
731	        const label = kids();
732	        return href ? `[${label || escapeMd(href)}](${href.replace(/\)/g, '%29').replace(/ /g, '%20')})` : label;
733	      }
734	      case 'IMG': return `![${escapeMd(node.getAttribute('alt') || '')}](${node.getAttribute('src') || ''})`;
735	      default: return kids();
736	    }
737	  }
