739	  function finishParagraph(text) {
740	    const cleaned = text.replace(/( {2}\n)+\s*$/, '').replace(/^\s+|\s+$/g, '');
741	    if (!cleaned) return '';
742	    return cleaned.split('\n').map((line) => escapeLineStart(line.replace(/^ (?! )/, ''))).join('\n');
743	  }
