745	  function blocksOf(nodes) {
746	    const out = [];
747	    let buf = '';
748	    const flush = () => {
749	      const p = finishParagraph(buf);
750	      if (p) out.push(p);
751	      buf = '';
752	    };
753	    for (const n of nodes) {
754	      if (isBlock(n)) {
755	        flush();
756	        const md = block(n);
757	        if (md) out.push(md);
758	      } else {
759	        buf += inline(n);
760	      }
761	    }
762	    flush();
