862	  /* ============================================================
863	     Folder handle persistence (IndexedDB)
864	     ============================================================ */
865	  const DB_NAME = 'capture-the-frag';
866	  const STORE = 'handles';
867	
868	  function idb(mode, fn) {
869	    return new Promise((resolve, reject) => {
870	      const open = indexedDB.open(DB_NAME, 1);
871	      open.onupgradeneeded = () => open.result.createObjectStore(STORE);
872	      open.onerror = () => reject(open.error);
873	      open.onsuccess = () => {
874	        const db = open.result;
875	        const tx = db.transaction(STORE, mode);
876	        const req = fn(tx.objectStore(STORE));
877	        tx.oncomplete = () => { db.close(); resolve(req && req.result); };
878	        tx.onerror = () => { db.close(); reject(tx.error); };
879	      };
880	    });
881	  }
882	  const idbGet = (key) => idb('readonly', (s) => s.get(key));
883	  const idbSet = (key, val) => idb('readwrite', (s) => s.put(val, key));
884	  const idbDel = (key) => idb('readwrite', (s) => s.delete(key));
885	
886	  async function ensurePermission(handle) {
887	    const opts = { mode: 'readwrite' };
888	    if ((await handle.queryPermission(opts)) === 'granted') return true;
889	    return (await handle.requestPermission(opts)) === 'granted';
890	  }
