895	
896	    if (handle) {
897	      if (!(await ensurePermission(handle))) {
898	        toast('Saving needs permission to edit the app folder.', true);
899	        return null;
900	      }
901	      try {
902	        // Confirm the folder still exists.
903	        await handle.getDirectoryHandle(SAVE_FOLDER, { create: true });
904	        return handle;
905	      } catch {
906	        await idbDel('appFolder').catch(() => {});
907	      }
908	    }
909	
910	    const picked = await window.showDirectoryPicker({ id: 'ctf-app-folder', mode: 'readwrite' });
911	    let looksRight = false;
912	    try { await picked.getFileHandle('index.html'); looksRight = true; } catch { /* not found */ }
913	    if (!looksRight) {
914	      const useAnyway = await confirmDialog(
915	        'Is this the app folder?',
916	        `<code>${escapeHtml(picked.name)}</code> doesn't contain <code>index.html</code>. Documents are saved to <code>${SAVE_FOLDER}/</code> inside the Capture the Frag folder. Use this folder anyway?`,
917	        'Use folder'
918	      );
919	      if (!useAnyway) return null;
920	    }
921	    await idbSet('appFolder', picked).catch(() => {});
922	    return picked;
923	  }
