935	    saving = true;
936	    btnSave.disabled = true;
937	    try {
938	      const appFolder = await getAppFolder();
939	      if (!appFolder) return;
940	      const folder = await appFolder.getDirectoryHandle(SAVE_FOLDER, { create: true });
941	      const name = fileName();
942	
943	      let exists = false;
944	      try { await folder.getFileHandle(name); exists = true; }
945	      catch (err) { if (err.name !== 'NotFoundError') throw err; }
946	
947	      if (exists) {
948	        const overwrite = await confirmDialog(
949	          'Replace existing document?',
