957	      const file = await folder.getFileHandle(name, { create: true });
958	      const writable = await file.createWritable();
959	      await writable.write(toMarkdown());
960	      await writable.close();
961	
962	      lastSavedName = name;
963	      setDirty(false);
964	      toast(`Saved <code>${SAVE_FOLDER}/${escapeHtml(name)}</code>`);
