#!/usr/bin/env node
// PostToolUse hook (matcher: ExitPlanMode).
// Copies the current session transcript (JSONL) verbatim into
//   <repo root>/documents/YYYY.MM.dd.<plan-title>.jsonl
// Override the target folder with the CLAUDE_PLAN_DOCS_DIR env var.
// Manual use: node save-plan-transcript.mjs < hook-input.json
// Never blocks the tool: all errors are swallowed and the script exits 0.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

function readStdin() {
  try { return fs.readFileSync(0, 'utf8'); } catch { return ''; }
}

function slug(s) {
  return String(s).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80);
}

function repoRoot(cwd) {
  try {
    return execFileSync('git', ['rev-parse', '--show-toplevel'], { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim();
  } catch { return cwd; }
}

try {
  const input = JSON.parse(readStdin() || '{}');
  const transcript = input.transcript_path;
  if (!transcript || !fs.existsSync(transcript)) process.exit(0);

  const cwd = input.cwd || process.cwd();
  const plan = (input.tool_input && input.tool_input.plan) || '';
  const heading = (plan.match(/^#\s+(.+)$/m) || [])[1];
  const title = slug(heading || '') || `plan-${String(input.session_id || 'session').slice(0, 8)}`;

  const dir = process.env.CLAUDE_PLAN_DOCS_DIR
    ? path.resolve(cwd, process.env.CLAUDE_PLAN_DOCS_DIR)
    : path.join(repoRoot(cwd), 'documents');
  fs.mkdirSync(dir, { recursive: true });

  const d = new Date();
  const stamp = `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2, '0')}.${String(d.getDate()).padStart(2, '0')}`;
  fs.copyFileSync(transcript, path.join(dir, `${stamp}.${title}.jsonl`));
} catch {
  // ignore — never block the session
}
process.exit(0);

