const C = window.captureTheFrag; const ed = C.editor; const out = {};
const md = `# Title

Some **bold** and *italic* and ~~strike~~ with \`code\` and [link](https://a.com).

- one
- two
  - nested
- [x] done

1. first
2. second

> quote line

\`\`\`js
const x = 1;
\`\`\`

| A | B |
| --- | --- |
| 1 | 2 |

---
`;
out.html = C.markdownToHtml(md);
ed.setContent(md, 'markdown');
ed.setMode('live');
const div = document.createElement('div'); div.innerHTML = C.FORMATS.markdown.render(md);
out.roundtrip = C.htmlToMarkdown(div);
out.same = out.roundtrip === md;
out.detect = [
  C.detectFormat({text: md}).id,
  C.detectFormat({text: '<div>\n<p>hi</p>\n</div>'}).id,
  C.detectFormat({text: 'just some words here.'}).id,
  C.detectFormat({html: '<meta charset="utf-8"><b id="docs-internal-guid-abc"><p><span style="font-weight:700">Hi</span></p></b>', text: 'Hi'}).id,
  C.detectFormat({html: '<p>Hello <strong>web</strong></p>', text: 'Hello web'}).id,
