const C = window.captureTheFrag; const ed = C.editor; const out = {};
// simulate first paste of markdown into empty editor
const md = "# Pasted\n\n- one\n- two\n- [ ] task\n\n1. a\n2. b\n\nText **bold**.\n";
const dt = new DataTransfer(); dt.setData('text/plain', md);
ed.live.focus();
ed.live.dispatchEvent(new ClipboardEvent('paste', {clipboardData: dt, bubbles: true, cancelable: true}));
out.fmtAfterFirst = ed.getFormat();
out.liveHtml = ed.live.innerHTML;
// second paste of rich html keeps markdown
const dt2 = new DataTransfer(); dt2.setData('text/html', '<p>Rich <strong>web</strong> text</p>'); dt2.setData('text/plain', 'Rich web text');
ed.live.dispatchEvent(new ClipboardEvent('paste', {clipboardData: dt2, bubbles: true, cancelable: true}));
await new Promise(r=>setTimeout(r,300));
out.fmtAfterSecond = ed.getFormat();
out.src = ed.getContent();
// raw mode command
ed.setMode('edit'); ed.raw.setSelectionRange(0,0); await ed.exec('bold');
out.rawStart = ed.raw.value.slice(0,30);
out.toolbarEdit = [...document.querySelectorAll('#toolbar [data-item]')].map(b=>b.dataset.item).join(',');
ed.setMode('preview');
out.toolbarPreview = [...document.querySelectorAll('#toolbar [data-item]')].map(b=>b.dataset.item).join(',');
ed.setMode('live');
out.ext = document.getElementById('extChip').textContent;
out.words = document.getElementById('wordCount').textContent;
out.state = document.getElementById('saveState').textContent;
out.folder = document.getElementById('folderName').textContent;
out;

